"""Regenerate ts/verifier/test/fixtures/zstd-packs.json from the Python reference.

    python ts/verifier/test/fixtures/make_fixtures.py

The conformance suite pins no compressor output (a zstd or zlib frame is not
reproducible across library versions), so the zstd paths of the TypeScript
reader -- codec 2 bodies, TINEPACK4 with zstd, TINEPACK5's long-distance frame
and its stored forms, storage-v3 local packs with BLOB_DELTA -- are checked
against inputs written once by the reference writers and committed here. The
expected answers are what the reference *readers* return for them.
"""

from __future__ import annotations

import hashlib
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[4]
sys.path.insert(0, str(ROOT))

from opentine import _codec  # noqa: E402
from opentine.kernel import ObjectEnvelope, canonical_json, validate_links  # noqa: E402
from opentine.repository import _pack4, _pack5  # noqa: E402
from opentine.repository import _run_delta as forms  # noqa: E402
from opentine.repository._pack_v3 import build_pack_v3, stored_forms  # noqa: E402
from opentine.repository.pack import inspect_pack  # noqa: E402
from tests.conformance.tagged import decode  # noqa: E402

OUT = Path(__file__).with_name("zstd-packs.json")


def objects() -> list[tuple[str, bytes]]:
    """Growing blobs, slim-able events, and one session's growing run snapshots."""
    text = "".join(f"turn {n}: the quick brown fox jumps over the lazy dog\n" for n in range(120))
    blobs = [ObjectEnvelope.create("blob", (text + "tail\n" * k).encode()) for k in range(1, 4)]
    events, parents = [], []
    for number, blob in enumerate(blobs):
        payload = {
            "actor": "",
            "attributes": {},
            "billing": {},
            "causal_ids": [],
            "cost": 0,
            "duration": 0,
            "input_blob": blob.oid,
            "kind": "model",
            "parent_ids": parents,
            "sequence": number,
            "usage": {},
        }
        event = ObjectEnvelope.create("event", payload)
        events.append(event)
        parents = [event.oid]
    runs = []
    for count in range(1, len(events) + 1):
        ids = [event.oid for event in events[:count]]
        payload = {
            "events": ids,
            "roots": ids[:1],
            "session_id": "fixture-session",
            "status": "running",
            "tips": ids[-1:],
        }
        runs.append(ObjectEnvelope.create("run", payload))
    return [(item.oid, item.encode()) for item in [*blobs, *events, *runs]]


def answer(data: bytes) -> dict:
    pack_id, packed, shallow = inspect_pack(data)
    return {
        "pack_id": pack_id,
        "objects": sorted(oid for oid, _ in packed),
        "shallow": sorted(shallow),
    }


def main() -> None:
    items = objects()
    # One object is left out so the pack has a shallow boundary.
    held_back = items[0][0]
    sent = [item for item in items if item[0] != held_back]
    shallow = sorted(
        {link for _, raw in sent for link in validate_links(ObjectEnvelope.decode(raw))}
        - {oid for oid, _ in sent}
    )
    assert shallow == [held_back]
    packs = {
        "v4-zlib": _pack4.build(sent, shallow, "zlib"),
        "v4-zstd": _pack4.build(sent, shallow, "zstd"),
        "v5-full": _pack5.build(sent, shallow),
        "v5-slim": _pack5.build(sent, shallow, slim=True),
    }
    slim = {f[2] for f in stored_forms(sent)}
    assert {forms.RUN_DELTA, forms.EVENT_SLIM} <= slim, slim
    digest, tpk, tidx = build_pack_v3(items, "zstd", None, blob_deltas=True)
    stored = {f[2] for f in stored_forms(items, blob_deltas=True)}
    assert {forms.BLOB_DELTA, forms.RUN_DELTA, forms.EVENT_SLIM} <= stored, stored

    vectors = json.loads((ROOT / "docs/conformance/vectors/53-sig-v4.json").read_text())["cases"]
    case = next(item for item in vectors if item["id"] == "sig3.verdict.verified-hmac")
    artifact = canonical_json(decode(case["input"]["value"]))
    fixture = {
        "note": "generated by make_fixtures.py from the Python reference; do not edit",
        "artifact": {
            "id": case["id"],
            "sha256": hashlib.sha256(artifact).hexdigest(),
            "zstd_wrapped_hex": _codec.wrap(artifact, "zstd", force=True).hex(),
        },
        "packs": {name: {"hex": data.hex(), **answer(data)} for name, data in packs.items()},
        "localpack": {
            "pack_id": digest,
            "tpk_hex": tpk.hex(),
            "tidx_hex": tidx.hex(),
            "objects": sorted([oid, hashlib.sha256(raw).hexdigest()] for oid, raw in items),
        },
    }
    OUT.write_text(json.dumps(fixture, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)} ({OUT.stat().st_size} bytes)")


if __name__ == "__main__":
    main()
